def _single_result(self, method, argument, non_block):
    # vLLM 0.12 requires a Future even for the synchronous executor.
    # Match UniProcExecutor: complete the same RPC, then wrap its result.
    if not non_block:
        return self.collective_rpc(method, args=(argument,))[0]
    from concurrent.futures import Future
    future = Future()
    try:
        future.set_result(self.collective_rpc(method, args=(argument,))[0])
    except Exception as exc:
        future.set_exception(exc)
    return future

def execute_model(self, scheduler_output, non_block=False):
    return self._single_result("execute_model", scheduler_output, non_block)

def sample_tokens(self, grammar_output, non_block=False):
    return self._single_result("sample_tokens", grammar_output, non_block)

